@SpringBootApplication
public class EnterpriseBootstrapper {
    public static void main(String[] args) {
        SpringApplication app = new SpringApplication(EnterpriseBootstrapper.class);
        app.addListeners(new ApplicationPidFileWriter());
        app.setWebApplicationType(WebApplicationType.SERVLET);
        ConfigurableApplicationContext context = app.run(args);

        // Inspecting bean definition count post-bootstrapping
        System.out.println("Total beans loaded: " + context.getBeanDefinitionCount());
    }
}
